mapper.select:
SELECT r.id, r.semester_id, r.type, r.change_type, r.target_user_id, r.payload_json, r.status,
       r.batch_no, r.applicant_id, r.reason, r.created_at, r.review_at,
       t.name AS targetUserName, t.user_no AS targetUserNo,
       tc.name AS currentCollegeName, tcl.name AS currentClassName,
       a.name AS applicantName
FROM change_request r
LEFT JOIN sys_user t ON t.id = r.target_user_id AND t.deleted = 0
LEFT JOIN sys_user a ON a.id = r.applicant_id AND a.deleted = 0
LEFT JOIN college tc ON tc.id = t.college_id AND tc.deleted = 0
LEFT JOIN school_class tcl ON tcl.id = t.class_id AND tcl.deleted = 0
WHERE r.deleted = 0
 AND r.semester_id = #{semesterId}
 AND r.status = #{status}
 AND r.batch_no = #{batchNo}
 AND r.type = #{type}
 AND r.change_type = #{changeType}
ORDER BY r.id DESC
LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(1) FROM change_request r
WHERE r.deleted = 0
 AND r.semester_id = #{semesterId}
 AND r.status = #{status}
 AND r.batch_no = #{batchNo}
 AND r.type = #{type}
 AND r.change_type = #{changeType}
